@Test
public void testMan() {
    String cmdLine = "man [-c|-f|-k|-w|-tZT device] [-adlhu7V] [-Mpath] [-Ppager] [-Slist] " + "[-msystem] [-pstring] [-Llocale] [-eextension] [section] page ...";
    Options options = new Options().addOption("a", "all", false, "find all matching manual pages.").addOption("d", "debug", false, "emit debugging messages.").addOption("e", "extension", false, "limit search to extension type 'extension'.").addOption("f", "whatis", false, "equivalent to whatis.").addOption("k", "apropos", false, "equivalent to apropos.").addOption("w", "location", false, "print physical location of man page(s).").addOption("l", "local-file", false, "interpret 'page' argument(s) as local filename(s)").addOption("u", "update", false, "force a cache consistency check.").//FIXME - should generate -r,--prompt string
    addOption("r", "prompt", true, "provide 'less' pager with prompt.").addOption("c", "catman", false, "used by catman to reformat out of date cat pages.").addOption("7", "ascii", false, "display ASCII translation or certain latin1 chars.").addOption("t", "troff", false, "use troff format pages.").//FIXME - should generate -T,--troff-device device
    addOption("T", "troff-device", true, "use groff with selected device.").addOption("Z", "ditroff", false, "use groff with selected device.").addOption("D", "default", false, "reset all options to their default values.").//FIXME - should generate -M,--manpath path
    addOption("M", "manpath", true, "set search path for manual pages to 'path'.").//FIXME - should generate -P,--pager pager
    addOption("P", "pager", true, "use program 'pager' to display output.").//FIXME - should generate -S,--sections list
    addOption("S", "sections", true, "use colon separated section list.").//FIXME - should generate -m,--systems system
    addOption("m", "systems", true, "search for man pages from other unix system(s).").//FIXME - should generate -L,--locale locale
    addOption("L", "locale", true, "define the locale for this particular man search.").//FIXME - should generate -p,--preprocessor string
    addOption("p", "preprocessor", true, "string indicates which preprocessor to run.\n" + " e - [n]eqn  p - pic     t - tbl\n" + " g - grap    r - refer   v - vgrind").addOption("V", "version", false, "show version.").addOption("h", "help", false, "show this usage message.");
    HelpFormatter hf = new HelpFormatter();
    final String EOL = System.getProperty("line.separator");
    StringWriter out = new StringWriter();
    hf.printHelp(new PrintWriter(out), 60, cmdLine, null, options, HelpFormatter.DEFAULT_LEFT_PAD, HelpFormatter.DEFAULT_DESC_PAD, null, false);
    assertEquals("usage: man [-c|-f|-k|-w|-tZT device] [-adlhu7V] [-Mpath]" + EOL + "           [-Ppager] [-Slist] [-msystem] [-pstring]" + EOL + "           [-Llocale] [-eextension] [section] page ..." + EOL + " -7,--ascii                display ASCII translation or" + EOL + "                           certain latin1 chars." + EOL + " -a,--all                  find all matching manual pages." + EOL + " -c,--catman               used by catman to reformat out of" + EOL + "                           date cat pages." + EOL + " -d,--debug                emit debugging messages." + EOL + " -D,--default              reset all options to their" + EOL + "                           default values." + EOL + " -e,--extension            limit search to extension type" + EOL + "                           'extension'." + EOL + " -f,--whatis               equivalent to whatis." + EOL + " -h,--help                 show this usage message." + EOL + " -k,--apropos              equivalent to apropos." + EOL + " -l,--local-file           interpret 'page' argument(s) as" + EOL + "                           local filename(s)" + EOL + " -L,--locale <arg>         define the locale for this" + EOL + "                           particular man search." + EOL + " -M,--manpath <arg>        set search path for manual pages" + EOL + "                           to 'path'." + EOL + " -m,--systems <arg>        search for man pages from other" + EOL + "                           unix system(s)." + EOL + " -P,--pager <arg>          use program 'pager' to display" + EOL + "                           output." + EOL + " -p,--preprocessor <arg>   string indicates which" + EOL + "                           preprocessor to run." + EOL + "                           e - [n]eqn  p - pic     t - tbl" + EOL + "                           g - grap    r - refer   v -" + EOL + "                           vgrind" + EOL + " -r,--prompt <arg>         provide 'less' pager with prompt." + EOL + " -S,--sections <arg>       use colon separated section list." + EOL + " -t,--troff                use troff format pages." + EOL + " -T,--troff-device <arg>   use groff with selected device." + EOL + " -u,--update               force a cache consistency check." + EOL + " -V,--version              show version." + EOL + " -w,--location             print physical location of man" + EOL + "                           page(s)." + EOL + " -Z,--ditroff              use groff with selected device." + EOL, out.toString());
}

